cases.append(("junk", "x"))
for status in ["active","lapsed","suspended","banned","weird","MISSING"]:
    for tier in ["basic","gold","platinum"]:
        for amount, method in [(0,"card"),(-5,"card"),(40,"card"),(100,"transfer"),("100","card"),(1,"paypal")]:
