                for st in [0,2,3,-1,"x"]: cases.append((members(status,tier,strikes=st),(amount,method)))
            elif status in ["active","banned","weird","MISSING"]:
                cases.append((members(status,tier),(amount,method)))

fails=0
for m,p in cases:
    mo = dict(m) if isinstance(m,dict) else m
    po = dict(p) if isinstance(p,dict) else p
    r1 = old.process_renewal(mo,po); r2 = new.process_renewal(dict(mo) if isinstance(mo,dict) else mo, dict(po) if isinstance(po,dict) else po)
    if r1 != r2:
        fails+=1; print("MISMATCH", m,p,r1,r2)
print("mismatches:", fails)
