from __future__ import annotations

GRACE_DAYS = 30
LATE_FEE = 15
REINSTATE_SURCHARGE = 25
MAX_STRIKES = 3
TIER_FEES = {"basic": 40, "gold": 90}
SUPPORTED_METHODS = ("card", "transfer")


def _active(tier: str, member: dict):
    """Active members renew at the base tier fee."""
    return None, TIER_FEES[tier], "renewed"


def _lapsed(tier: str, member: dict):
    """Lapsed members pay a surcharge that grows the longer they were out."""
    days = member.get("expired_days")
    if not isinstance(days, int) or days < 0:
        return "bad expiry", None, None
    if days <= GRACE_DAYS:
        return None, TIER_FEES[tier] + LATE_FEE, "renewed"
    return None, TIER_FEES[tier] + REINSTATE_SURCHARGE, "reinstated"


def _suspended(tier: str, member: dict):
    """Suspended members must be under the strike limit to reactivate."""
    strikes = member.get("strikes")
    if not isinstance(strikes, int) or strikes < 0:
        return "bad strikes", None, None
